// Port of c/dec/prefix.h (brotli v1.1.0).
//
// kCmdLut's 704 CmdLutElement entries (5,632 bytes) are stored below as an RVA
// byte blob — each record is the exact little-endian in-memory image of the C
// struct: { u8 insert_len_extra_bits, u8 copy_len_extra_bits, i8 distance_code,
// u8 context, u16le insert_len_offset, u16le copy_len_offset } — and decoded
// once at static init into native memory for pointer-stable hot-path access
// (PORTING.md data-table rule). Values were extracted mechanically from the C
// initializer and are spot-checked against the C source in StaticDataTests.
//
// The block-length prefix code table lives in its v1.1.0 C home instead:
// BrotliConstants._kBrotliPrefixCodeRanges (c/common/constants.{h,c}).
// kInsBase/kInsExtra/kCopyBase/kCopyExtra do not exist in v1.1.0's decoder
// (kCmdLut covers them); the encoder-side equivalents in c/enc/prefix.h are
// out of scope until the encoder stages.

using System.Runtime.InteropServices;

namespace DnBrotli.Dec;

/// <summary><c>struct CmdLutElement</c>, field-for-field (8 bytes, no padding).</summary>
internal struct CmdLutElement
{
    public byte insert_len_extra_bits;
    public byte copy_len_extra_bits;
    public sbyte distance_code;
    public byte context;
    public ushort insert_len_offset;
    public ushort copy_len_offset;
}

internal static unsafe class Prefix
{
    /// <summary><c>static const CmdLutElement kCmdLut[BROTLI_NUM_COMMAND_SYMBOLS]</c> —
    /// pointer to the 704-entry table (native memory, initialized once, never freed,
    /// exactly like the C static).</summary>
    internal static readonly CmdLutElement* kCmdLut;

    static Prefix()
    {
        /* Decoded field-by-field, not memcpy'd: the 8-byte LE records match .NET's
           packed CmdLutElement layout, but the dn2cpp backend widens small struct
           fields to int32 (different size AND offsets), so only per-field stores
           are layout-agnostic. The allocation is sized with sizeof(CmdLutElement),
           which both runtimes lower to their own layout's size. */
        ReadOnlySpan<byte> blob = kCmdLutData;
        int n = blob.Length / 8;
        CmdLutElement* lut = (CmdLutElement*)NativeMemory.Alloc((nuint)n * (nuint)sizeof(CmdLutElement));
        for (int i = 0; i < n; ++i)
        {
            lut[i].insert_len_extra_bits = blob[8 * i];
            lut[i].copy_len_extra_bits = blob[8 * i + 1];
            lut[i].distance_code = (sbyte)blob[8 * i + 2];
            lut[i].context = blob[8 * i + 3];
            lut[i].insert_len_offset = (ushort)(blob[8 * i + 4] | (blob[8 * i + 5] << 8));
            lut[i].copy_len_offset = (ushort)(blob[8 * i + 6] | (blob[8 * i + 7] << 8));
        }
        kCmdLut = lut;
    }

